import { z } from 'zod';
import { REST_API } from '../../api';
export enum CipherType {
    AES_128_GCM = 5,
    AES_256_GCM = 6,
    CHACHA20_POLY1305 = 7,
    NONE = 9,
    UNKNOWN = 0,
    UNRECOGNIZED = -1,
    XCHACHA20_POLY1305 = 8,
}
export namespace AddUserCommand {
    export const url = REST_API.HANDLER.ADD_USER;
    const BaseTrojanUser = z.object({
        type: z.literal('trojan'),
        tag: z.string(),
        username: z.string(),
        password: z.string(),
        level: z.number().default(0),
    });
    const BaseVlessUser = z.object({
        type: z.literal('vless'),
        tag: z.string(),
        username: z.string(),
        uuid: z.string(),
        flow: z.enum(['xtls-rprx-vision', '']),
        level: z.number().default(0),
    });
    const BaseShadowsocksUser = z.object({
        type: z.literal('shadowsocks'),
        tag: z.string(),
        username: z.string(),
        password: z.string(),
        cipherType: z.nativeEnum(CipherType),
        ivCheck: z.boolean(),
        level: z.number().default(0),
    });
    const BaseShadowsocks2022User = z.object({
        type: z.literal('shadowsocks2022'),
        tag: z.string(),
        username: z.string(),
        key: z.string(),
        level: z.number().default(0),
    });
    const BaseSocksUser = z.object({
        type: z.literal('socks'),
        tag: z.string(),
        username: z.string(),
        socks_username: z.string(),
        socks_password: z.string(),
        level: z.number().default(0),
    });
    const BaseHttpUser = z.object({
        type: z.literal('http'),
        tag: z.string(),
        username: z.string(),
        http_username: z.string(),
        http_password: z.string(),
        level: z.number().default(0),
    });
    export const RequestSchema = z.object({
        data: z.array(
            z.discriminatedUnion('type', [
                BaseTrojanUser,
                BaseVlessUser,
                BaseShadowsocksUser,
                BaseShadowsocks2022User,
                BaseSocksUser,
                BaseHttpUser,
            ]),
        ),
    });
    export type Request = z.infer<typeof RequestSchema>;
    export const ResponseSchema = z.object({
        response: z.object({
            success: z.boolean(),
            error: z.string().nullable(),
        }),
    });
    export type Response = z.infer<typeof ResponseSchema>;
}

